    assert(raw.every(e => e.ad_id === 'house'));
    for (let i = 0; i < 12; i++) assert.equal(normalized[i].eventId, normalized[i + 12].eventId);
    ssai.sendAdBeacon('another-viewer', 'ad_start', 'house', starts[0]);
    const other = normalizeEvent(JSON.parse(await sent.at(-1)));
    assert(!normalized.some(e => e.eventId === other.eventId));
    console.log(`${useBeacon ? 'sendBeacon' : 'fetch'}: repeat airings, refresh, restart, session isolation passed against reference normalizer`);
  }
})().catch(e => { console.error(e); process.exitCode = 1; });
